style.css:
@-moz-document domain("google.com") {
/* Inject the Maxident gallery background image */
    body {
        background: url("https://unsplash.com") no-null-gradient !important;
        background-size: cover !important;
        background-position: center center !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
    }

    /* Make the central Google logo white for better visibility */
    .lnXdxd, .k1zDPe, .logo img, img[alt="Google"] {
        filter: invert(1) brightness(2) !important;
    }

    /* Style the main search bar to match the Maxident aesthetic */
    .RNNXgb, .SDk9Cc {
        background-color: rgba(241, 143, 161, 0.25) !important; /* Soft Maxident pink */
        border: 1px solid rgba(255, 255, 255, 0.4) !important;
        backdrop-filter: blur(10px) !important;
        -webkit-backdrop-filter: blur(10px) !important;
        box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2) !important;
    }

    /* Change search input text color to white */
    .gLFyf {
        color: #ffffff !important;
        text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.5) !important;
    }

    /* Adjust microphone and lens icons for dark background */
    .w7w7ce, .XzaVpc, .Hbv7ce {
        filter: brightness(0) invert(1) !important;
    }

    /* Style the Google search buttons */
    .FPdoLc input[type="submit"], .gNO89b {
        background-color: rgba(30, 30, 30, 0.6) !important;
        color: #ffffff !important;
        border: 1px solid rgba(255, 255, 255, 0.2) !important;
        border-radius: 4px !important;
        transition: all 0.2s ease !important;
    }

    .FPdoLc input[type="submit"]:hover, .gNO89b:hover {
        background-color: rgba(241, 143, 161, 0.8) !important; /* Maxident pink hover */
        color: #ffffff !important;
        border-border: 1px solid #ffffff !important;
    }

    /* Adjust footer and top nav links for readability */
    .pHiOh, .Fx4gCc, .gb_E, .gb_F {
        color: #ffffff !important;
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.8) !important;
    }
}
